// PR117355
#define STR "bbbbbbbbbbbbbbbbbbbbbbbbbbb"

void
__attribute__ ((noinline))
test9 (void)
{
  char line[256];
  const char *p = STR;
  const char *q = p + sizeof (STR) - 1;

  char *q1 = line;
  for (const char *p1 = p; p1 < q;)
    {
      *q1++ = *p1++;

      if (p1 < q && (*q1++ = *p1++) != '\0')
	{
	  if (__builtin_object_size (q1 - 2, 0) == 0)
	    __builtin_abort ();
	  if (__builtin_object_size (q1 - 2, 1) == 0)
	    __builtin_abort ();
	}
    }
}

  test9 ();
